package edu.compiler.generator;

import edu.compiler.ast.python.PythonAst.FunctionDef;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public final class WebRuntimeEmitter {
    public String prelude(){return """
        # Generated by Restricted Web Compiler. Python standard library only.
        import html as __cpl_html
        import http.server as __cpl_http
        import os as __cpl_os
        import pathlib as __cpl_pathlib
        import re as __cpl_re
        import sys as __cpl_sys
        import urllib.parse as __cpl_url

        class Application:
            def __init__(self):
                pass

        class __CplResponse:
            def __init__(self, status, body='', headers=None):
                self.status, self.body, self.headers = status, body, headers or {}

        class __CplRequest:
            def __init__(self, form=None):
                self.form = form or {}

        request = __CplRequest()

        def __cpl_get(context, name):
            if name not in context:
                raise KeyError("undefined template value: " + name)
            return context[name]

        def __cpl_attr(value, name):
            return value[name] if isinstance(value, dict) else getattr(value, name)

        def __cpl_escape(value):
            return '' if value is None else __cpl_html.escape(str(value), quote=True)

        def __cpl_render_attr(raw, context):
            pattern = __cpl_re.compile(r'{{\\s*([A-Za-z_][A-Za-z0-9_]*(?:\\.[A-Za-z_][A-Za-z0-9_]*)*)\\s*}}')
            def replace(match):
                parts = match.group(1).split('.')
                value = __cpl_get(context, parts[0])
                for part in parts[1:]:
                    value = __cpl_attr(value, part)
                return __cpl_escape(value)
            return pattern.sub(replace, raw)

        def redirect(path):
            if not isinstance(path, str) or not path.startswith('/') or path.startswith('//'):
                raise ValueError('redirect target must be a local absolute path')
            return __CplResponse(303, headers={'Location': path})

        """;}
    public String finish(List<FunctionDef> functions){
        List<FunctionDef> routes=functions.stream().filter(x->x.route!=null).sorted(Comparator.comparingInt((FunctionDef x)->dynamicCount(x.route.path))).toList();
        StringBuilder out=new StringBuilder("""

        def render_template(name, **context):
            renderer = __cpl_templates.get(name)
            if renderer is None:
                raise KeyError('unknown template: ' + name)
            return renderer(context)

        __cpl_routes = [
        """);
        for(FunctionDef route:routes)for(String method:route.route.methods)out.append("    (").append(TemplateEmitter.pyString(method)).append(", ").append(TemplateEmitter.pyString(route.route.path)).append(", ").append(route.name).append("),\n");
        out.append("""
        ]

        def __cpl_match(pattern, path):
            pattern_parts = [p for p in pattern.split('/') if p]
            path_parts = [p for p in path.split('/') if p]
            if len(pattern_parts) != len(path_parts):
                return None
            values = []
            for expected, actual in zip(pattern_parts, path_parts):
                dynamic = __cpl_re.fullmatch(r'<int:([A-Za-z_][A-Za-z0-9_]*)>', expected)
                if dynamic:
                    if not __cpl_re.fullmatch(r'-?[0-9]+', actual): return None
                    values.append(int(actual))
                elif expected != actual: return None
            return values

        class __CplHandler(__cpl_http.BaseHTTPRequestHandler):
            def do_GET(self): self.__dispatch('GET')
            def do_POST(self): self.__dispatch('POST')
            def __dispatch(self, method):
                global request
                path = __cpl_url.urlsplit(self.path).path
                if path.startswith('/static/'):
                    if method != 'GET': return self.__send(__CplResponse(405, 'Method Not Allowed'))
                    return self.__static(path[8:])
                path_exists = False
                for route_method, pattern, handler in __cpl_routes:
                    values = __cpl_match(pattern, path)
                    if values is None: continue
                    path_exists = True
                    if route_method != method: continue
                    try:
                        form = {}
                        if method == 'POST':
                            size = int(self.headers.get('Content-Length', '0'))
                            if size < 0 or size > 1048576: return self.__send(__CplResponse(400, 'Bad Request'))
                            parsed = __cpl_url.parse_qs(self.rfile.read(size).decode('utf-8'), keep_blank_values=True)
                            form = {key: values[0] for key, values in parsed.items()}
                        request = __CplRequest(form)
                        response = handler(*values)
                        if not isinstance(response, __CplResponse): response = __CplResponse(200, '' if response is None else str(response))
                        return self.__send(response)
                    except (KeyError, ValueError, UnicodeDecodeError): return self.__send(__CplResponse(400, 'Bad Request'))
                    except Exception: return self.__send(__CplResponse(500, 'Internal Server Error'))
                return self.__send(__CplResponse(405 if path_exists else 404, 'Method Not Allowed' if path_exists else 'Not Found'))
            def __static(self, relative):
                root = (__cpl_pathlib.Path(__file__).parent / 'static').resolve()
                target = (root / relative).resolve()
                if root not in target.parents or not target.is_file() or target.suffix != '.css': return self.__send(__CplResponse(404, 'Not Found'))
                response = __CplResponse(200, target.read_text(encoding='utf-8'), {'Content-Type': 'text/css; charset=utf-8'})
                return self.__send(response)
            def __send(self, response):
                body = response.body.encode('utf-8')
                self.send_response(response.status)
                self.send_header('Content-Type', response.headers.get('Content-Type', 'text/html; charset=utf-8'))
                self.send_header('Content-Length', str(len(body)))
                for name, value in response.headers.items():
                    if name != 'Content-Type': self.send_header(name, value)
                self.end_headers()
                if body: self.wfile.write(body)
            def log_message(self, format, *args):
                print(format % args)

        def __cpl_serve(port=8000):
            server = __cpl_http.ThreadingHTTPServer(('127.0.0.1', port), __CplHandler)
            print(f'Serving on http://127.0.0.1:{port}')
            server.serve_forever()

        if __name__ == '__main__':
            __cpl_serve(int(__cpl_sys.argv[1]) if len(__cpl_sys.argv) > 1 else int(__cpl_os.environ.get('PORT', '8000')))
        """);return out.toString();
    }
    private int dynamicCount(String path){return (int)path.chars().filter(x->x=='<').count();}
}

